#!/usr/bin/env python3
"""Run from the repo root after unzipping: python3 ui_apply.py   (idempotent; keeps your other edits to app.js, index.html, docs.css, site.css)"""
import re
LAYOUT = 'function renderLayout() {\nconst host = $("#rjd");\nif (!host) return;\nconst nm = (k) => prof.files.find((x) => x.kind === k).name.replace(/\\.[^.]+$/, ""),\nrow = (l, v, n) => `<div class="rjd-r"><span>${esc(l)}</span><b>${esc(v)}</b>${n ? `<i class="rjd-n" aria-hidden="true">${n}</i>` : ""}</div>`,\ncard = (ic, t, n, rows) =>\n`<section class="rjd-c"><header><span class="rjd-i" aria-hidden="true">${ic}</span><h3>${esc(t)}</h3><i class="rjd-n" aria-hidden="true">${n}</i><span class="rjd-t" aria-hidden="true"></span></header>${rows}</section>`,\nW = \'<svg viewBox="0 0 24 24" aria-hidden="true">\';\nhost.innerHTML =\ncard(W + \'<path d="M3 12c2.2-6 4.4-6 6 0s3.8 6 6 0 3.8-6 6 0"/></svg>\', "ViPER-DDC", 1, row("DDC file", nm("vdc"))) +\ncard(W + \'<path d="M4 12h1.5M8 8v8M12 4.5v15M16 8v8M19 12h1.5"/></svg>\', "Convolver", 2, row("Impulse response", nm("irs")) + row("Impulse response optimization", "Original")) +\ncard(W + \'<path d="M9 7l-5 5 5 5M15 7l5 5-5 5"/></svg>\', "Live programmable DSP", 3, row("Liveprog script", prof.script));\n}\n'
FIG = '<figure class="appfig">\n<div class="rjd" id="rjd" role="group" aria-label="Layout of the RootlessJamesDSP main screen with your profile\'s files"></div>\n<figcaption>\nA schematic of the RootlessJamesDSP main screen, filled in with the\nfiles for your profile. Cards 1 to 3 follow the first three steps. The app lists\nfiles without their extension, and the script by its title.\n<details class="rjd-real"><summary>See a real screenshot</summary>\n<img src="assets/img/app-layout.webp" width="540" height="1002" alt="Screenshot of the RootlessJamesDSP main screen with ViPER-DDC, Convolver and Live programmable DSP switched on, showing example file names" loading="lazy" decoding="async"/>\n<span>Taken from the app with an earlier speaker profile, so its file names differ from yours.</span>\n</details>\n</figcaption>\n</figure>'
DOCS = '/* ===== evidence matrix v2: quiet marks, exceptions stand out ===== */\n.evx-m{--cw:46px;border-collapse:separate;border-spacing:0}\n.evx-m thead th{font:600 10px/1 var(--mono);letter-spacing:.1em;color:var(--mut);padding:10px 0 8px;border-bottom:1px solid var(--bd2)}\n.evx-m thead tr:first-child th{padding:10px 0 8px;border-bottom:0}\n.evx-m thead .grp{color:var(--tx);letter-spacing:.16em;background:color-mix(in srgb,var(--tx) 4%,transparent);border-bottom:0;\n border-radius:8px 8px 0 0;box-shadow:inset 0 -2px 0 color-mix(in srgb,var(--acc) 55%,transparent)}\n.evx-m thead .grp + .grp{box-shadow:inset 0 -2px 0 color-mix(in srgb,var(--tx) 18%,transparent)}\n.evx-m thead tr:first-child th:first-child{background:none;box-shadow:none}\n.evx-m tbody th,.evx-m tbody td{vertical-align:middle;padding:0;height:46px;border-bottom:1px solid color-mix(in srgb,var(--bd) 70%,transparent)}\n.evx-m tbody th{padding:0 12px 0 4px;font:600 13px/1.3 var(--sans);letter-spacing:-.005em}\n.evx-m tbody td{width:var(--cw);min-width:var(--cw)}\n.evx-m tbody td::after{display:none}\n.evx-m tbody tr:hover th,.evx-m tbody tr:hover td{background:color-mix(in srgb,var(--tx) 3.5%,transparent)}\n.evx-m tbody tr:last-child th,.evx-m tbody tr:last-child td{border-bottom:0}\n.evx-m td:nth-child(4){box-shadow:-1px 0 0 var(--bd)}\n.evx-m .dot{width:26px;height:26px;border:0;border-radius:50%;font:600 13px/1 var(--sans);background:transparent;color:var(--tx);position:relative;transition:transform .15s,box-shadow .15s}\n.evx-m .dot.pass{background:color-mix(in srgb,var(--tx) 9%,transparent);color:var(--tx2)}\n.evx-m .dot.warn{background:color-mix(in srgb,var(--warning,#d9a441) 20%,transparent);color:var(--warning,#d9a441);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--warning,#d9a441) 55%,transparent)}\n.evx-m .dot.fail{background:color-mix(in srgb,var(--danger,#e5675b) 20%,transparent);color:var(--danger,#e5675b);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--danger,#e5675b) 55%,transparent)}\n.evx-m .dot.not_run,.evx-m .dot.untested{background:none;border:0;color:var(--mut);opacity:.55;font-size:15px}\n.evx-m button.dot{background:none}\n.evx-m button.dot.pass{background:color-mix(in srgb,var(--tx) 9%,transparent)}\n.evx-m button.dot.warn{background:color-mix(in srgb,var(--warning,#d9a441) 20%,transparent)}\n.evx-m button.dot.fail{background:color-mix(in srgb,var(--danger,#e5675b) 20%,transparent)}\n.evx-m button.dot.not_run,.evx-m button.dot.untested{background:none}\n.evx-m button.dot:hover{transform:scale(1.12);box-shadow:0 0 0 3px color-mix(in srgb,var(--acc) 28%,transparent)}\n.evx-m button.dot:focus-visible{outline:2px solid var(--acc);outline-offset:2px}\n.tw:has(.evx-m){border-radius:var(--r-lg,16px);padding:4px 12px 4px}\n.evx-lg{gap:6px 18px;padding:2px 4px}\n.evx-lg .dot{width:20px;height:20px;font-size:11px;border:0}\n.evx-lg .dot.pass{background:color-mix(in srgb,var(--tx) 9%,transparent);color:var(--tx2)}\n.evx-lg .dot.warn{background:color-mix(in srgb,var(--warning,#d9a441) 20%,transparent);color:var(--warning,#d9a441)}\n.evx-lg .dot.fail{background:color-mix(in srgb,var(--danger,#e5675b) 20%,transparent);color:var(--danger,#e5675b)}\n.evx-lg .dot.not_run,.evx-lg .dot.untested{background:none;color:var(--mut);opacity:.7}\n@media(max-width:560px){\n .evx-m{--cw:32px;font-size:12px}\n .evx-m tbody th{font-size:12.5px;padding-right:6px}.evx-m tbody th small{display:none}\n .evx-m tbody th,.evx-m tbody td{height:44px}\n .evx-m .dot{width:24px;height:24px;font-size:12px}\n .evx-m thead th{font-size:9px;letter-spacing:.04em}\n .tw:has(.evx-m){padding:2px 8px}\n}\n'
SITE = '/* RootlessJamesDSP layout schematic (replaces the raw screenshot as the primary figure) */\n.rjd{display:grid;gap:10px;padding:12px;border:1px solid var(--bd2);border-radius:var(--r-lg,18px);background:linear-gradient(180deg,color-mix(in srgb,var(--surface) 92%,var(--tx) 3%),var(--surface));box-shadow:var(--lift)}\n.rjd-c{border:1px solid var(--bd);border-radius:var(--r-md);background:color-mix(in srgb,var(--bg) 55%,transparent);overflow:hidden}\n.rjd-c header{display:flex;align-items:center;gap:10px;padding:11px 12px;background:color-mix(in srgb,var(--acc) 9%,var(--surface));border-bottom:1px solid var(--bd)}\n.rjd-c h3{margin:0;font:600 13.5px/1.2 var(--sans);letter-spacing:-.005em;flex:1;min-width:0}\n.rjd-i{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:color-mix(in srgb,var(--acc) 15%,transparent);color:var(--acc);flex:none}\n.rjd-i svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}\n.rjd-t{width:34px;height:20px;border-radius:99px;background:var(--acc);position:relative;flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.15)}\n.rjd-t::after{content:"";position:absolute;top:3px;right:3px;width:14px;height:14px;border-radius:50%;background:#111}\n.rjd-n{display:inline-grid;place-items:center;min-width:20px;height:20px;border-radius:50%;background:var(--acc);color:#111;font:700 11px/1 var(--mono);font-style:normal;flex:none;box-shadow:0 0 0 3px color-mix(in srgb,var(--acc) 22%,transparent)}\n.rjd-c header .rjd-n{order:3}.rjd-c header .rjd-t{order:4}\n.rjd-r{display:grid;gap:3px;padding:10px 12px;border-top:1px solid color-mix(in srgb,var(--bd) 70%,transparent);position:relative}\n.rjd-r:first-of-type{border-top:0}\n.rjd-r span{font-size:12px;color:var(--tx2)}\n.rjd-r b{font:600 12.5px/1.35 var(--mono);color:var(--tx);overflow-wrap:anywhere}\n.rjd-r .rjd-n{display:none}\n.rjd-real{margin-top:10px}\n.rjd-real summary{cursor:pointer;color:var(--tx2);font-size:12px;min-height:32px;display:flex;align-items:center}\n.rjd-real img{display:block;width:100%;height:auto;max-width:300px;margin:8px 0;border-radius:var(--r-md);border:1px solid var(--bd2)}\n.rjd-real span{display:block;color:var(--mut);font-size:11.5px}\n'
def rw(p, f):
    s = open(p, encoding='utf-8').read(); n = f(s)
    if n != s: open(p, 'w', encoding='utf-8').write(n); print('patched', p)
    else: print('unchanged', p)
rw('site/assets/js/app.js', lambda s: s if 'function renderLayout' in s else s.replace('function renderApply() {', LAYOUT + 'function renderApply() {\nrenderLayout();', 1))
def fig(s):
    a = s.index('<figure class="appfig">'); b = s.index('</figure>', a) + 9
    return s[:a] + FIG + s[b:]
rw('site/index.html', lambda s: s if 'id="rjd"' in s else fig(s))
rw('site/assets/css/docs.css', lambda s: s if 'evidence matrix v2' in s else s.rstrip('\n') + '\n\n' + DOCS)
rw('site/assets/css/site.css', lambda s: s if 'layout schematic' in s else s.rstrip('\n') + '\n' + SITE)
print('next: python3 build/seo.py && python3 build/docs_site.py && python3 tests/check.py')
